export class Sidebar {
  constructor(container) {
    this.container = container;
    this.navItems = [
      { id: 'list', label: '知识库列表', icon: '📚' },
      { id: 'detail', label: '知识库详情', icon: '📄' },
      { id: 'userChat', label: '用户聊天', icon: '💬' },
    ];
    this.kbItems = [
      { id: 'kb1', label: '产品文档中心', count: '128 文档', icon: '📄' },
      { id: 'kb2', label: '客服知识库', count: '256 问答', icon: '💬' },
      { id: 'kb3', label: '法规政策库', count: '45 文档', icon: '📑' },
      { id: 'kb4', label: '技术博客汇总', count: '312 文档', icon: '🌐' },
      { id: 'kb5', label: '内部培训资料', count: '86 文档', icon: '📚' },
      { id: 'kb6', label: '竞品分析库', count: '24 文档', icon: '📊' },
    ];
    this.systemItems = [
      { id: 'settings', label: '设置', icon: '⚙️' },
      { id: 'theme', label: '主题', icon: '🎨' },
    ];
    this.activeItem = 'list';
    this.activeKB = 'kb1';
    this.render();
  }

  render() {
    this.container.innerHTML = `
      <aside class="sidebar">
        <div class="logo">
          <div class="logo-icon">S</div>
          SSO Hub
        </div>
        <nav class="nav">
          <div class="nav-section">知识库</div>
          ${this.navItems
            .map(
              (item) => `
            <div
              class="nav-item ${this.activeItem === item.id ? 'active' : ''}"
              data-id="${item.id}"
            >
              ${item.icon} ${item.label}
            </div>
          `
            )
            .join('')}
          <div class="nav-section">我的知识库</div>
          ${this.kbItems
            .map(
              (item) => `
            <div
              class="nav-item kb-item ${this.activeKB === item.id ? 'active' : ''}"
              data-id="${item.id}"
            >
              ${item.icon} ${item.label}
              <div class="kb-item-count">${item.count}</div>
            </div>
          `
            )
            .join('')}
          <div class="nav-section">系统</div>
          ${this.systemItems
            .map(
              (item) => `
            <div
              class="nav-item ${this.activeItem === item.id ? 'active' : ''}"
              data-id="${item.id}"
            >
              ${item.icon} ${item.label}
            </div>
          `
            )
            .join('')}
        </nav>
      </aside>
    `;

    this.bindEvents();
  }

  bindEvents() {
    this.container.addEventListener('click', (e) => {
      const navItem = e.target.closest('.nav-item');
      if (navItem) {
        const id = navItem.dataset.id;
        if (this.kbItems.find((item) => item.id === id)) {
          this.activeKB = id;
          this.activeItem = 'detail';
          const kb = this.kbItems.find((item) => item.id === id);
          this.onKBSelect?.(kb);
        } else {
          this.activeItem = id;
        }
        this.render();
        this.onNavChange?.(id);
      }
    });
  }

  setOnNavChange(callback) {
    this.onNavChange = callback;
  }

  setOnKBSelect(callback) {
    this.onKBSelect = callback;
  }

  setActive(itemId) {
    this.activeItem = itemId;
    this.render();
  }
}
